for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\nPair {i+1}: '{inp}' → '{outp}'")
    print(f"Length: {len(inp)} → {len(outp)}")
    if len(inp) == len(outp):
        for j, (in_char, out_char) in enumerate(zip(inp, outp)):
            if in_char != out_char:
                print(f"  Position {j}: '{in_char}' → '{out_char}'")
    else:
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' → '{out_char}'")
        if len(inp) < len(outp):
            print(f"  Extra chars in output: {outp[len(inp):]}")
        else:
            print(f"  Extra chars in input: {inp[len(outp):]}")

